class Allocator {
    private int[] mem;
    public Allocator(int n) { mem = new int[n]; }
    public int allocate(int size, int mID) {
        int count = 0;
        for (int i = 0; i < mem.length; i++) {
            if (mem[i] == 0) count++; else count = 0;
            if (count == size) {
                for (int j = i; j > i - size; j--) mem[j] = mID;
                return i - size + 1;
            }
        }
        return -1;
    }
    public int free(int mID) {
        int count = 0;
        for (int i = 0; i < mem.length; i++)
            if (mem[i] == mID) { mem[i] = 0; count++; }
        return count;
    }
}

import java.util.*;

class Allocator {
    private int n;
    private List<int[]> intervals;
    public Allocator(int n) {
        this.n = n;
        intervals = new ArrayList();
    }
    public int allocate(int size, int mID) {
        int prev = 0;
        for (int i = 0; i < intervals.size(); i++) {
            int[] interval = intervals.get(i);
            if (interval[0] - prev >= size) {
                intervals.add(i, new int[]{prev, prev + size, mID});
                return prev;
            }
            prev = interval[1];
        }
        if (n - prev >= size) {
            intervals.add(new int[]{prev, prev + size, mID});
            return prev;
        }
        return -1;
    }
    public int free(int mID) {
        int count = 0;
        Iterator<int[]> it = intervals.iterator();
        while (it.hasNext()) {
            int[] interval = it.next();
            if (interval[2] == mID) {
                count += interval[1] - interval[0];
                it.remove();
            }
        }
        return count;
    }
}
